-- FUEL RETAIL WAREHOUSE - INITIAL LOAD
-- Azure SQL Database / SQL Server T-SQL
-- Re-runnable reset: deletes existing tables and recreates all data.
-- Data is synthetic; 5 matching baseline tables + 2 fuel-specific extra tables.
-- All timestamps are sample data.
SET NOCOUNT ON;

DROP TABLE IF EXISTS dbo.FactInventoryReading;
DROP TABLE IF EXISTS dbo.FactFuelSale;
DROP TABLE IF EXISTS dbo.DimPump;
DROP TABLE IF EXISTS dbo.DimDate;
DROP TABLE IF EXISTS dbo.DimFuelProduct;
DROP TABLE IF EXISTS dbo.DimStation;
DROP TABLE IF EXISTS dbo.DimCustomer;

CREATE TABLE dbo.DimCustomer (customer_id INT NOT NULL PRIMARY KEY,customer_name VARCHAR(120) NOT NULL,customer_code VARCHAR(30) NOT NULL,customer_type VARCHAR(30) NOT NULL,city VARCHAR(80),registration_date DATE,updated_at DATETIME2(0) NOT NULL);
CREATE TABLE dbo.DimStation (station_id INT NOT NULL PRIMARY KEY,station_name VARCHAR(160) NOT NULL,brand VARCHAR(80),city VARCHAR(80),state VARCHAR(80),postal_code VARCHAR(15),ownership_type VARCHAR(40),updated_at DATETIME2(0) NOT NULL);
CREATE TABLE dbo.DimFuelProduct (product_id INT NOT NULL PRIMARY KEY,product_name VARCHAR(120) NOT NULL,fuel_code VARCHAR(30) NOT NULL,fuel_category VARCHAR(50),unit_of_measure VARCHAR(10),list_price DECIMAL(10,2),updated_at DATETIME2(0) NOT NULL);
CREATE TABLE dbo.DimDate (date_key INT NOT NULL PRIMARY KEY,full_date DATE NOT NULL,day_of_month INT,month_number INT,calendar_year INT,weekday_name VARCHAR(20));
CREATE TABLE dbo.DimPump (pump_id INT NOT NULL PRIMARY KEY,station_id INT NOT NULL REFERENCES dbo.DimStation(station_id),pump_code VARCHAR(30),pump_status VARCHAR(30),nozzle_count INT,updated_at DATETIME2(0) NOT NULL);
CREATE TABLE dbo.FactFuelSale (sale_id BIGINT NOT NULL PRIMARY KEY,customer_id INT NOT NULL REFERENCES dbo.DimCustomer(customer_id),station_id INT NOT NULL REFERENCES dbo.DimStation(station_id),product_id INT NOT NULL REFERENCES dbo.DimFuelProduct(product_id),pump_id INT NULL REFERENCES dbo.DimPump(pump_id),date_key INT NOT NULL REFERENCES dbo.DimDate(date_key),quantity_litres DECIMAL(12,3) NOT NULL,unit_price DECIMAL(10,2) NOT NULL,gross_amount DECIMAL(14,2) NOT NULL,discount_amount DECIMAL(12,2) NOT NULL,net_amount DECIMAL(14,2) NOT NULL,payment_method VARCHAR(30),sale_timestamp DATETIME2(0) NOT NULL,updated_at DATETIME2(0) NOT NULL);
CREATE TABLE dbo.FactInventoryReading (reading_id BIGINT NOT NULL PRIMARY KEY,station_id INT NOT NULL REFERENCES dbo.DimStation(station_id),product_id INT NOT NULL REFERENCES dbo.DimFuelProduct(product_id),date_key INT NOT NULL REFERENCES dbo.DimDate(date_key),opening_stock_litres DECIMAL(14,3),received_litres DECIMAL(14,3),sold_litres DECIMAL(14,3),closing_stock_litres DECIMAL(14,3),reading_timestamp DATETIME2(0) NOT NULL,updated_at DATETIME2(0) NOT NULL);

-- DimCustomer: 500 rows

-- DimStation: 500 rows

-- DimFuelProduct: 500 rows

-- DimDate: 365 rows

-- DimPump: 200 rows

-- FactFuelSale: 1,000 rows

-- FactInventoryReading: 400 rows

-- Expected table counts: 500 customers, 500 stations, 500 products, 365 dates, 200 pumps, 1000 sales, 400 inventory readings.
-- Total initial rows: 3465.
SELECT DimCustomer AS table_name,COUNT(*) AS row_count FROM dbo.DimCustomer UNION ALL
SELECT DimStation,COUNT(*) FROM dbo.DimStation UNION ALL
SELECT DimFuelProduct,COUNT(*) FROM dbo.DimFuelProduct UNION ALL
SELECT DimDate,COUNT(*) FROM dbo.DimDate UNION ALL
SELECT DimPump,COUNT(*) FROM dbo.DimPump UNION ALL
SELECT FactFuelSale,COUNT(*) FROM dbo.FactFuelSale UNION ALL
SELECT FactInventoryReading,COUNT(*) FROM dbo.FactInventoryReading;
